Object.assign(EN, TRIP.en, V7.en, V10.en, V11.en);
const DICT = { en: EN, de: { ...DE, ...EXTRA.de, ...TRIP.de, ...V7.de, ...V10.de, ...V11.de }, es: { ...ES, ...EXTRA.es }, it: { ...IT, ...EXTRA.it }, fr: { ...FR, ...EXTRA.fr }, hi: HI, pa: PA, zh: ZH, ko: KO };
let cur = 'en';
try { const s = JSON.parse(localStorage.getItem('bl1') || '{}'); if (s.lang && DICT[s.lang]) cur = s.lang; } catch (e) { /* ignore */ }

export const getLang = () => cur;
export const setLang = (l) => { if (DICT[l]) cur = l; };
export function tr(key, vars) {
  let s = DICT[cur][key];
  if (s === undefined) s = EN[key];
  if (s === undefined) return key;
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] !== undefined ? vars[k] : m));
  return s;
}
export const cnt = (key, n) => tr(key + (n === 1 ? '1' : 'N'), { n });

const tf = {};
const fm = (o) => { const k = cur + JSON.stringify(o); return tf[k] || (tf[k] = new Intl.DateTimeFormat(LOCALE[cur], { timeZone: 'Europe/Berlin', ...o })); };
export const fmtTime = (ms) => fm({ hour: '2-digit', minute: '2-digit', hour12: false }).format(ms);
export const fmtDay = (ms) => fm({ weekday: 'short', day: 'numeric', month: 'short' }).format(ms);
export const dict = DICT;
